<form class="razorpay-form" id="{{ $formId }}"><div class="row g-3"><div class="col-12"><label class="form-label" for="{{ $formId }}-name">Your name</label><input class="form-control" id="{{ $formId }}-name" name="name" autocomplete="name" required maxlength="150"></div><div class="col-12"><label class="form-label" for="{{ $formId }}-email">Email address</label><input class="form-control" id="{{ $formId }}-email" type="email" name="email" autocomplete="email" required></div><div class="col-12"><label class="form-label" for="{{ $formId }}-contact">Contact number</label><input class="form-control" id="{{ $formId }}-contact" name="contact" autocomplete="tel" required></div><div class="col-4"><label class="form-label" for="{{ $formId }}-currency">Currency</label><select class="form-select" id="{{ $formId }}-currency" name="currency"><option value="{{ $currency }}">{{ $currency }}</option></select></div><div class="col-8"><label class="form-label" for="{{ $formId }}-amount">Amount</label><input class="form-control" id="{{ $formId }}-amount" type="number" name="amount" min="1" max="1000000" step="0.01" required placeholder="Enter amount"></div><div class="col-12"><label class="form-label" for="{{ $formId }}-receipt">Manuscript ID <small>(optional)</small></label><input class="form-control" id="{{ $formId }}-receipt" name="receipt" maxlength="100"></div></div><button class="btn btn-isar w-100 mt-3" type="submit" @disabled(!$razorpayConfigured)><i class="fa-solid fa-lock"></i> Pay Now with Razorpay</button>@unless($razorpayConfigured)<p class="gateway-unavailable"><i class="fa-solid fa-circle-info"></i> Razorpay is temporarily unavailable. Please contact the editorial office.</p>@endunless<p class="gateway-message" role="status" aria-live="polite"></p></form>
